#!/usr/bin/env python3
import csv, json, math, os, pathlib, shutil, subprocess, sys, wave
import numpy as np

ROOT = pathlib.Path(__file__).resolve().parents[1]
EUR = ROOT / "third_party" / "eurorack"
STM = ROOT / "third_party" / "stmlib"
PATCH = ROOT / "build" / "upstream-dsp-compile" / "source-patches"
WORK = ROOT / "build" / "rings-delay-test"
OUT = WORK / "results"
OUT.mkdir(parents=True, exist_ok=True)

# Use the five-model overlay generated by check_upstream_dsp_compile.py.
part_h = (PATCH / "rings/dsp/part.h").read_text()
part_cc = (PATCH / "rings/dsp/part.cc").read_text()
assert "STRING_AND_REVERB" not in part_h + part_cc
# Match the FM-1 I2S frame rate: 24 MHz / 544 ticks = 44,117.647... Hz.
dsp_h = (EUR / "rings/dsp/dsp.h").read_text().replace("48000.0f", "44117.6470588f")
(PATCH / "rings/dsp").mkdir(parents=True, exist_ok=True)
(PATCH / "rings/dsp/dsp.h").write_text(dsp_h)

# Float reference uses the pinned original string header. Q15 build substitutes
# only the two Rings delay arrays (2048 + 1024 samples per String).
orig_string = (EUR / "rings/dsp/string.h").read_text()
q15_string = orig_string.replace(
    '#include "stmlib/stmlib.h"',
    '#include "stmlib/stmlib.h"\n#include "q15_delay_line.h"').replace(
    "typedef stmlib::DelayLine<float, kDelayLineSize> StringDelayLine;\ntypedef stmlib::DelayLine<float, kDelayLineSize / 2> StiffnessDelayLine;",
    "typedef Q15DelayLine<kDelayLineSize> StringDelayLine;\ntypedef Q15DelayLine<kDelayLineSize / 2> StiffnessDelayLine;")
if q15_string == orig_string:
    raise SystemExit("Could not apply Q15 String/Stiffness delay typedef overlay")
q15_header = ROOT / "tools" / "rings_delay_test" / "q15_delay_line.h"
(PATCH / "rings/dsp/q15_delay_line.h").write_text(q15_header.read_text())

sources = sorted(set(list((EUR / "rings/dsp").glob("*.cc")) + [EUR / "rings/resources.cc"] +
                         list((STM / "dsp").glob("*.cc")) + list((STM / "utils").glob("*.cc"))))
sources = [PATCH / "rings/dsp/part.cc" if p.name == "part.cc" else p for p in sources if "string_synth" not in p.name]
main = ROOT / "tools" / "rings_delay_test" / "main.cc"
include = ["-I" + str(PATCH), "-I" + str(ROOT / "tools/rings_delay_test"),
           "-I" + str(ROOT / "third_party"),
           "-I" + str(EUR), "-I" + str(STM)]
common = ["g++", "-std=c++11", "-O2", "-D_GNU_SOURCE", "-DTEST", "-ffunction-sections", "-fdata-sections",
          "-Wno-unused-function", "-Wno-unused-variable", *include]
for variant, extra in (("float", []), ("q15", ["-DRINGS_DELAY_Q15"])):
    build = WORK / variant
    build.mkdir(parents=True, exist_ok=True)
    (PATCH / "rings/dsp/string.h").write_text(q15_string if variant == "q15" else orig_string)
    objects = []
    for src in sources:
        obj = build / (src.name + ".o")
        cmd = [*common, *extra, "-c", str(src), "-o", str(obj)]
        subprocess.run(cmd, cwd=ROOT, check=True)
        objects.append(str(obj))
    exe = build / "rings_delay_test"
    subprocess.run([*common, *extra, str(main), *objects, "-Wl,--gc-sections", "-o", str(exe)],
                   cwd=ROOT, check=True)
    subprocess.run([str(exe), str(build / "audio.f32")], cwd=build, check=True)

a = np.fromfile(WORK / "float/audio.f32", dtype=np.float32)
b = np.fromfile(WORK / "q15/audio.f32", dtype=np.float32)
if a.size != b.size or a.size % 2:
    raise SystemExit(f"Float/Q15 output length mismatch: {a.size} vs {b.size}")
a = a.reshape(-1, 2); b = b.reshape(-1, 2)
diff = b - a
rms = lambda x: float(np.sqrt(np.mean(np.asarray(x, dtype=np.float64)**2)))
peak_a, peak_b = float(np.max(np.abs(a))), float(np.max(np.abs(b)))
rms_err = rms(diff)
snr = 20.0 * math.log10(max(rms(a), 1e-15) / max(rms_err, 1e-15))
segments = list(csv.DictReader(open(WORK / "float/segments.csv", newline="")))
metrics = []
def peak_hz(x):
    x = np.asarray(x, dtype=np.float64)
    x = x - np.mean(x)
    if len(x) < 256 or np.max(np.abs(x)) < 1e-7: return None
    win = np.hanning(len(x)); spec = np.abs(np.fft.rfft(x * win))
    lo = max(1, int(35 * len(x) / 44117.647))
    hi = min(len(spec), int(4000 * len(x) / 44117.647))
    if hi <= lo: return None
    k = lo + int(np.argmax(spec[lo:hi]))
    return k * 44117.647 / len(x)
for s in segments:
    start, n = int(s["start"]), int(s["frames"])
    x, y = a[start:start+n], b[start:start+n]
    e = y - x
    # Estimate dominant partial after the initial 150 ms transient.
    p0 = int(0.15 * 44117.647); p1 = min(n, int(0.75 * 44117.647))
    fx = peak_hz(np.mean(x[p0:p1], axis=1)); fy = peak_hz(np.mean(y[p0:p1], axis=1))
    cents = (1200.0 * math.log2(fy/fx)) if fx and fy else None
    decay = None
    if s["profile"] == "long_decay":
        vals = []
        for t in (0.5, 1.0, 2.0, 4.0):
            lo, hi = int(t*44117.647), int((t+0.25)*44117.647)
            if hi <= n: vals.append({"t_s":t,"float_rms":rms(x[lo:hi]),"q15_rms":rms(y[lo:hi])})
        decay = vals
    metrics.append({"model":int(s["model"]),"note":int(s["note"]),"profile":s["profile"],
                    "rms_error":rms(e),"snr_db":20*math.log10(max(rms(x),1e-15)/max(rms(e),1e-15)),
                    "dominant_partial_cents":cents,"decay_windows":decay,
                    "float_peak":float(np.max(np.abs(x))),"q15_peak":float(np.max(np.abs(y)))})
def read_stats(path):
    values = {}
    raw = path.read_text()
    for line in raw.splitlines():
        if "=" in line:
            k,v=line.split("=",1); values[k]=float(v)
    return values
stats = read_stats(WORK / "q15/delay_stats.txt")
float_stats = read_stats(WORK / "float/delay_stats.txt")
summary = {"sample_rate_hz_exact":24000000/544,"wav_sample_rate_hz":44118,
           "samples_per_channel":int(a.shape[0]),"float_peak":peak_a,"q15_peak":peak_b,
           "rms_error":rms_err,"snr_db":snr,"output_samples_over_full_scale_float":int(np.count_nonzero(np.abs(a)>1.0)),
           "output_samples_over_full_scale_q15":int(np.count_nonzero(np.abs(b)>1.0)),
           "q15_delay_saturation_count":int(stats["q15_saturation_count"]),
           "q15_delay_max_abs_before_quantisation":stats["q15_max_abs"],"float_part_size_bytes":float_stats["part_size_bytes"],"q15_part_size_bytes":stats["part_size_bytes"],"part_size_saving_bytes":float_stats["part_size_bytes"]-stats["part_size_bytes"],"segments":metrics}
(OUT / "metrics.json").write_text(json.dumps(summary,indent=2)+"\n")
# Same fixed PCM conversion for both; deliberately no per-file normalisation.
for name, data in (("rings-float-reference.wav",a),("rings-int16-delay.wav",b)):
    pcm = np.clip(data, -1.0, 1.0)
    pcm = np.rint(pcm * 32767.0).astype("<i2")
    with wave.open(str(OUT/name),"wb") as w:
        w.setnchannels(2); w.setsampwidth(2); w.setframerate(44118); w.writeframes(pcm.tobytes())
print(json.dumps({k:v for k,v in summary.items() if k!="segments"},indent=2))
print("WAVs written with identical fixed gain; neither file was normalised independently.")
